#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    // Tối ưu I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n;
    int k;
    if (cin >> n >> k) {
        if (k == 0) {
            if (n == 0) { cout << 0 << "\n"; return 0; }
            string res = "";
            while (n > 0) {
                res += to_string(n % 2);
                n /= 2;
            }
            reverse(res.begin(), res.end());
            cout << res << "\n";
        } else if (k == 1) {
            if (n == 0) { cout << 0 << "\n"; return 0; }
            string res = "";
            char hex_chars[] = "0123456789ABCDEF";
            while (n > 0) {
                res += hex_chars[n % 16];
                n /= 16;
            }
            reverse(res.begin(), res.end());
            cout << res << "\n";
        } else if (k == 2) {
            long long sum = 0;
            while (n > 0) {
                sum += n % 10;
                n /= 10;
            }
            cout << sum << "\n";
        }
    }
    return 0;
}

