#include <iostream>
#include <vector>
#include <deque>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    long long current_sum = 0;
    deque<int> max_dq, min_dq;

    for (int i = 0; i < n; ++i) {
        current_sum += a[i];

        // Loại bỏ các chỉ số đã trượt ra ngoài cửa sổ k
        if (!max_dq.empty() && max_dq.front() == i - k) max_dq.pop_front();
        if (!min_dq.empty() && min_dq.front() == i - k) min_dq.pop_front();

        // Loại bỏ các phần tử không có khả năng làm Max trong tương lai
        while (!max_dq.empty() && a[max_dq.back()] <= a[i]) max_dq.pop_back();
        max_dq.push_back(i);

        // Loại bỏ các phần tử không có khả năng làm Min trong tương lai
        while (!min_dq.empty() && a[min_dq.back()] >= a[i]) min_dq.pop_back();
        min_dq.push_back(i);

        // Cửa sổ bắt đầu đủ kích thước k
        if (i >= k - 1) {
            cout << current_sum << " " << a[max_dq.front()] << " " << a[min_dq.front()] << "\n";
            current_sum -= a[i - k + 1]; // Trừ đi phần tử ngoài cùng bên trái để chuẩn bị cho bước lặp sau
        }
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MAX = 1000000;
int spf[MAX + 1];
vector<int> primes;

// Sàng Eratosthenes và mảng lưu thừa số nguyên tố nhỏ nhất
void sieve() {
    for (int i = 1; i <= MAX; i++) spf[i] = i;
    for (int i = 2; i * i <= MAX; i++) {
        if (spf[i] == i) {
            for (int j = i * i; j <= MAX; j += i) {
                if (spf[j] == j)
                    spf[j] = i;
            }
        }
    }
    for (int i = 2; i <= MAX; i++) {
        if (spf[i] == i) {
            primes.push_back(i);
        }
    }
}

long long countDivisors(long long n) {
    long long divisors = 1;
    // Tối ưu 1: Dùng mảng spf (O(log n)) cho n <= 10^6
    if (n <= MAX) {
        while (n != 1) {
            int prime = spf[n];
            int count = 0;
            while (n % prime == 0) {
                count++;
                n /= prime;
            }
            divisors *= (count + 1);
        }
        return divisors;
    } else {
        // Tối ưu 2: Dùng danh sách số nguyên tố cho số lớn
        for (int p : primes) {
            if (1LL * p * p > n) break;
            if (n % p == 0) {
                int count = 0;
                while (n % p == 0) {
                    count++;
                    n /= p;
                }
                divisors *= (count + 1);
            }
        }
        // Nếu n phần dư ra là số nguyên tố
        if (n > 1) {
            divisors *= 2;
        }
        return divisors;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    sieve();

    int n;
    if (cin >> n) {
        for (int i = 0; i < n; i++) {
            long long x;
            cin >> x;
            cout << countDivisors(x) << (i == n - 1 ? "" : " ");
        }
        cout << "\n";
    }
    return 0;
}

